{"t":"say","text":"I'll design a private hybrid setup connecting your on-premises data center to Jakarta VPC via Express Connect, hosting MongoDB and RDS."}
{"t":"req","text":"Databases hosted in Jakarta region","regions":["ap-southeast-5"]}
{"t":"req","text":"No public internet exposure for databases"}
{"t":"plan","products":["onprem-dc","express-connect","vpc","mongodb","rds","privatezone"]}
{"t":"group","id":"onprem","kind":"onprem","label":"On-premises Data Center","parent":null}
{"t":"node","id":"app-servers","product":"onprem-dc","label":"SaaS App Servers","group":"onprem","why":"Runs application servers entirely in own facility."}
{"t":"group","id":"jakarta","kind":"region","label":"Jakarta (ap-southeast-5)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Database VPC","parent":"jakarta"}
{"t":"node","id":"express-connect","product":"express-connect","label":"Express Connect","group":"vpc","why":"Dedicated private link from data center to VPC."}
{"t":"edge","id":"e-app-servers-express-connect","from":"app-servers","to":"express-connect","label":"private","kind":"data"}
{"t":"node","id":"mongodb","product":"mongodb","label":"Managed MongoDB","group":"vpc","zones":["a","b"],"why":"Managed MongoDB instance reachable only privately."}
{"t":"node","id":"rds","product":"rds","label":"RDS PostgreSQL","group":"vpc","zones":["a","b"],"why":"Managed PostgreSQL database with HA standby."}
{"t":"edge","id":"e-express-connect-mongodb","from":"express-connect","to":"mongodb","label":"private","kind":"data"}
{"t":"edge","id":"e-express-connect-rds","from":"express-connect","to":"rds","label":"private","kind":"data"}
{"t":"node","id":"privatezone","product":"privatezone","label":"PrivateZone","group":"vpc","attachTo":"vpc","why":"Resolves database endpoints privately inside the VPC."}
{"t":"done","summary":"Private hybrid architecture linking your data center to Jakarta VPC via Express Connect, hosting managed MongoDB and RDS PostgreSQL without public exposure."}

{"t":"say","text":"I'll design a hardened live-streaming platform with Anti-DDoS Proxy scrubbing traffic before ESA, then ALB to app servers and cache."}
{"t":"plan","products":["users","dns","anti-ddos-proxy","esa","alb","waf","ecs","tair","live","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Viewers and Streamers","group":"internet","why":"People watching or broadcasting live streams."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the platform domain to Anti-DDoS Proxy."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge Defense","parent":null}
{"t":"node","id":"anti-ddos","product":"anti-ddos-proxy","label":"Anti-DDoS Proxy","group":"edge","why":"Scrubs large L3-L7 DDoS attacks before traffic reaches ESA."}
{"t":"edge","id":"e-users-anti-ddos","from":"users","to":"anti-ddos","label":"HTTPS"}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets, accelerates dynamic API calls and adds bot management."}
{"t":"edge","id":"e-anti-ddos-esa","from":"anti-ddos","to":"esa","label":"scrubbed"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Streaming VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Distributes HTTP/HTTPS traffic across app servers in two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF 3.0","group":"vpc","attachTo":"alb","why":"Blocks OWASP injection attacks and CC floods at the load balancer."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App Servers","group":"vpc","zones":["a","b"],"why":"Runs streaming platform business logic and API handlers."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app","label":"HTTP"}
{"t":"node","id":"cache","product":"tair","label":"Session Cache","group":"vpc","zones":["a","b"],"why":"Stores viewer sessions, room state and hot metadata for low latency."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache","label":"Redis"}
{"t":"node","id":"live","product":"live","label":"ApsaraVideo Live","group":"sg","why":"Ingests, transcodes and distributes the actual live video streams."}
{"t":"edge","id":"e-app-live","from":"app","to":"live","label":"control"}
{"t":"node","id":"media","product":"oss","label":"Media Storage","group":"sg","why":"Stores recorded streams, thumbnails and static web assets."}
{"t":"edge","id":"e-live-media","from":"live","to":"media","label":"recordings"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Centralizes access logs and security events for alerting."}
{"t":"edge","id":"e-alb-logs","from":"alb","to":"logs","kind":"control"}
{"t":"done","summary":"Live-streaming platform with Anti-DDoS Proxy scrubbing into ESA, ALB with WAF, ECS app servers and Tair cache."}

{"t":"say","text":"I'll design a self-hosted Dify on ACK in Frankfurt, calling Qwen via Model Studio and reading company docs from OSS."}
{"t":"plan","products":["users","dns","alb","dify-on-ack","ack","acr","model-studio","oss","milvus","rds","tair","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internet","why":"Internal staff asking questions to the knowledge assistant."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves the internal assistant domain to the ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"frankfurt","kind":"region","label":"Frankfurt (eu-central-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Dify VPC","parent":"frankfurt"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes employee HTTPS traffic into the cluster."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Kubernetes cluster hosting the Dify workloads."}
{"t":"edge","id":"e-alb-ack","from":"alb","to":"ack","label":"HTTP"}
{"t":"node","id":"dify","product":"dify-on-ack","label":"Dify","group":"vpc","attachTo":"ack","why":"Self-hosted low-code agent and RAG builder for the assistant."}
{"t":"node","id":"acr","product":"acr","label":"Container Registry","group":"frankfurt","why":"Stores Dify container images pulled by ACK."}
{"t":"edge","id":"e-ack-acr","from":"ack","to":"acr","label":"pull","kind":"control"}
{"t":"node","id":"model","product":"model-studio","label":"Model Studio","group":"frankfurt","why":"Serves Qwen models for answering employee questions."}
{"t":"edge","id":"e-dify-model","from":"ack","to":"model","label":"LLM API"}
{"t":"node","id":"docs","product":"oss","label":"Company documents","group":"frankfurt","why":"Holds source documents that Dify ingests for RAG."}
{"t":"edge","id":"e-dify-docs","from":"ack","to":"docs","label":"read"}
{"t":"node","id":"vector","product":"milvus","label":"Milvus vector store","group":"vpc","zones":["a","b"],"why":"Stores document embeddings for retrieval-augmented generation."}
{"t":"edge","id":"e-dify-vector","from":"ack","to":"vector","label":"query"}
{"t":"node","id":"db","product":"rds","label":"RDS PostgreSQL","group":"vpc","zones":["a","b"],"why":"Persists Dify metadata, workflows and chat history."}
{"t":"edge","id":"e-dify-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"Caches sessions and speeds up repeated queries."}
{"t":"edge","id":"e-dify-cache","from":"ack","to":"cache","label":"Redis"}
{"t":"node","id":"logs","product":"sls","label":"SLS logs","group":"frankfurt","why":"Collects Dify application logs for troubleshooting."}
{"t":"edge","id":"e-dify-logs","from":"ack","to":"logs","kind":"control"}
{"t":"done","summary":"Dify self-hosted on ACK in Frankfurt, using Model Studio for Qwen, OSS for documents, Milvus for vectors, RDS and Tair."}

{"t":"say","text":"I'll draw a product catalog API with ESA, ALB, compute, RDS for the catalog and OSS for images. Elasticsearch is excluded."}
{"t":"req","text":"Avoid Elasticsearch due to licensing concerns","avoid":["elasticsearch"]}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","rds","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Marketplace shoppers","group":"internet","why":"Customers browsing the product catalog."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the marketplace domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches catalog responses and product images globally."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Catalog VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes API requests across two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects the catalog API from attacks."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"api","product":"ecs","label":"Catalog API servers","group":"vpc","zones":["a","b"],"why":"Serves product data and search queries."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"api","why":"Scales servers during traffic spikes."}
{"t":"edge","id":"e-alb-api","from":"alb","to":"api","label":"HTTP"}
{"t":"say","text":"Product metadata goes to RDS and images to OSS, both highly available."}
{"t":"node","id":"db","product":"rds","label":"Product catalog DB","group":"vpc","zones":["a","b"],"why":"Stores product details, prices and categories."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"SQL"}
{"t":"node","id":"images","product":"oss","label":"Product images","group":"sg","why":"Stores product photos served via ESA."}
{"t":"edge","id":"e-api-images","from":"api","to":"images","label":"read/write"}
{"t":"edge","id":"e-esa-images","from":"esa","to":"images","label":"cache"}
{"t":"node","id":"logs","product":"sls","label":"API logs","group":"sg","why":"Centralized logging for troubleshooting."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"done","summary":"Product catalog API behind ESA and ALB with WAF, ECS with Auto Scaling, RDS for data and OSS for images."}

{"t":"say","text":"I'll add OpenSearch for fast full-text and fuzzy search over product titles and descriptions, avoiding Elasticsearch."}
{"t":"req","text":"Avoid Elasticsearch due to licensing concerns","avoid":["elasticsearch"]}
{"t":"node","id":"search","product":"opensearch","label":"Product search index","group":"vpc","why":"Full-text and fuzzy search over product titles and descriptions."}
{"t":"edge","id":"e-api-search","from":"api","to":"search","label":"query"}
{"t":"done","summary":"Added OpenSearch for full-text and fuzzy product search; Elasticsearch remains excluded per legal policy."}

{"t":"say","text":"I'll design a photo-sharing backend with ECS behind an ALB, RDS for metadata, and OSS for images. No serverless functions."}
{"t":"req","text":"No serverless functions allowed","avoid":["fc"]}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","rds","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"App users","group":"internet","why":"People uploading and viewing photos."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the app domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches photos and accelerates uploads globally."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"App VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes HTTP traffic across two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks malicious requests before reaching ECS."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"Photo app servers","group":"vpc","zones":["a","b"],"why":"Runs the photo-sharing API on ECS instances."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Scales ECS fleet based on CPU load."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Metadata goes to RDS and uploaded photos are stored in OSS."}
{"t":"node","id":"db","product":"rds","label":"Metadata DB","group":"vpc","zones":["a","b"],"why":"Stores user data and photo metadata reliably."}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"images","product":"oss","label":"Photo storage","group":"sg","why":"Durable object storage for all uploaded images."}
{"t":"edge","id":"e-app-images","from":"app","to":"images","label":"upload"}
{"t":"edge","id":"e-esa-images","from":"esa","to":"images","label":"fetch"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects application logs for monitoring and debugging."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"done","summary":"Photo-sharing backend with ESA, ALB with WAF, ECS with Auto Scaling, RDS for metadata, and OSS for images."}

{"t":"say","text":"Since Function Compute is forbidden, I'll add an ECS worker that polls OSS via SMQ events to generate thumbnails."}
{"t":"req","text":"No serverless functions allowed","avoid":["fc"]}
{"t":"node","id":"queue","product":"smq","label":"Thumbnail queue","group":"sg","why":"Receives OSS upload events to trigger thumbnail jobs."}
{"t":"node","id":"worker","product":"ecs","label":"Thumbnail workers","group":"vpc","zones":["a","b"],"why":"Polls the queue and generates thumbnails from uploaded photos."}
{"t":"edge","id":"e-images-queue","from":"images","to":"queue","label":"events","kind":"async"}
{"t":"edge","id":"e-queue-worker","from":"queue","to":"worker","label":"poll","kind":"async"}
{"t":"edge","id":"e-worker-images","from":"worker","to":"images","label":"write thumbs"}
{"t":"done","summary":"Added SMQ for OSS events and ECS thumbnail workers to generate images without using serverless functions."}

{"t":"say","text":"I'll design a claims portal for your Japanese insurance company, keeping all policyholder data strictly within the Tokyo region."}
{"t":"req","text":"All policyholder data must remain physically within Japan","regions":["ap-northeast-1"]}
{"t":"plan","products":["users","dns","esa","alb","waf","sae","rds","oss","sls","kms"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Policyholders","group":"internet","why":"Insurance customers submitting claims and documents."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the claims portal domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates portal access and provides edge security."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"tk","kind":"region","label":"Tokyo (ap-northeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Claims VPC","parent":"tk"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes HTTPS traffic to the portal across two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects the claims portal from web attacks."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"portal","product":"sae","label":"Claims Portal","group":"vpc","zones":["a","b"],"why":"Serverless app hosting the claims submission portal."}
{"t":"edge","id":"e-alb-portal","from":"alb","to":"portal"}
{"t":"say","text":"Now adding the database, document storage, encryption and logging, all in Tokyo."}
{"t":"node","id":"db","product":"rds","label":"Claims Database","group":"vpc","zones":["a","b"],"why":"Stores claim records with high availability in Tokyo."}
{"t":"edge","id":"e-portal-db","from":"portal","to":"db","label":"SQL"}
{"t":"node","id":"docs","product":"oss","label":"Claim Documents","group":"tk","why":"Stores policyholder document uploads securely in Tokyo."}
{"t":"edge","id":"e-portal-docs","from":"portal","to":"docs","label":"uploads"}
{"t":"node","id":"kms","product":"kms","label":"KMS","group":"tk","why":"Encrypts stored documents and database backups at rest."}
{"t":"edge","id":"e-portal-kms","from":"portal","to":"kms","kind":"control","label":"encrypt"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"tk","why":"Centralized audit logs for compliance and monitoring."}
{"t":"edge","id":"e-portal-logs","from":"portal","to":"logs","kind":"control"}
{"t":"done","summary":"Tokyo-only claims portal using SAE, RDS, OSS, ESA, ALB with WAF, KMS and SLS for full data residency."}

{"t":"say","text":"I cannot replicate policyholder data to Singapore because your pinned requirement keeps all data physically within Japan."}
{"t":"say","text":"Instead, I'll add a read replica in Tokyo and let the analytics team access it securely from Singapore via Cloud Enterprise Network."}
{"t":"node","id":"db-replica","product":"rds","label":"Analytics Read Replica","group":"vpc","zones":["a","b"],"why":"Tokyo read replica for reporting, keeping data in Japan per regulation."}
{"t":"edge","id":"e-db-db-replica","from":"db","to":"db-replica","label":"replication","kind":"async"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc-sg","kind":"vpc","label":"Analytics VPC","parent":"sg"}
{"t":"node","id":"cen","product":"cen","label":"CEN","group":null,"why":"Private cross-region network linking Singapore analytics to Tokyo replica."}
{"t":"node","id":"dashboard","product":"ecs","label":"Reporting Dashboard","group":"vpc-sg","zones":["a","b"],"why":"Runs BI dashboards for the Singapore analytics team."}
{"t":"edge","id":"e-dashboard-cen","from":"dashboard","to":"cen","label":"private","kind":"data"}
{"t":"edge","id":"e-cen-db-replica","from":"cen","to":"db-replica","label":"SQL read","kind":"data"}
{"t":"done","summary":"Added a Tokyo read replica and CEN so Singapore analysts query data privately without leaving Japan."}

{"t":"say","text":"I'll add a Qwen-powered chatbot to the claims portal, keeping all data processing within Tokyo."}
{"t":"plan","products":["model-studio","ai-gateway"]}
{"t":"node","id":"ai-gw","product":"ai-gateway","label":"AI Gateway","group":"vpc","why":"Routes and guards LLM calls from the portal."}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio (Qwen)","group":"tk","why":"Answers policyholder questions via Qwen models."}
{"t":"edge","id":"e-portal-ai-gw","from":"portal","to":"ai-gw","label":"chat"}
{"t":"edge","id":"e-ai-gw-llm","from":"ai-gw","to":"llm","label":"LLM API"}
{"t":"done","summary":"Added AI Gateway in the VPC and Model Studio in Tokyo so the portal can serve a Qwen chatbot while keeping data local."}

{"t":"req","text":"이용자 개인정보는 반드시 서울 리전에 보관, 해외 반출 금지","regions":["ap-northeast-2"]}
{"t":"say","text":"서울(ap-northeast-2) 리전 내에서 게임 서버와 플레이어 DB를 구성하고, ESA로 글로벌 유저의 접속 지연을 줄이는 아키텍처를 설계합니다."}
{"t":"plan","products":["users","dns","esa","alb","ecs","tair","rds","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"인터넷","parent":null}
{"t":"node","id":"users","product":"users","label":"플레이어","group":"internet","why":"게임에 접속하는 전 세계 유저"}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"게임 도메인을 ESA 엣지로 해석"}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"엣지","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"글로벌 엣지에서 DDoS 방어 및 트래픽 가속"}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"게임 트래픽"}
{"t":"group","id":"seoul","kind":"region","label":"Seoul (ap-northeast-2)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"게임 VPC","parent":"seoul"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"두 가용영역으로 게임 트래픽 분산"}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"백엔드 전달"}
{"t":"node","id":"gameserver","product":"ecs","label":"게임 서버","group":"vpc","zones":["a","b"],"why":"게임 로직 처리, 서울 리전 내 데이터 보관"}
{"t":"edge","id":"e-alb-gameserver","from":"alb","to":"gameserver","label":"요청 전달"}
{"t":"say","text":"세션 캐시와 플레이어 DB를 추가하여 성능과 안정성을 확보합니다."}
{"t":"node","id":"cache","product":"tair","label":"세션 캐시","group":"vpc","zones":["a","b"],"why":"플레이어 세션 및 실시간 상태 고속 저장"}
{"t":"node","id":"db","product":"rds","label":"플레이어 DB","group":"vpc","zones":["a","b"],"why":"개인정보 포함 플레이어 데이터 영구 저장"}
{"t":"edge","id":"e-gameserver-cache","from":"gameserver","to":"cache","label":"세션 조회"}
{"t":"edge","id":"e-gameserver-db","from":"gameserver","to":"db","label":"데이터 읽기/쓰기"}
{"t":"node","id":"assets","product":"oss","label":"게임 에셋 스토리지","group":"seoul","why":"패치 파일 및 정적 에셋 저장"}
{"t":"edge","id":"e-esa-assets","from":"esa","to":"assets","label":"에셋 제공"}
{"t":"node","id":"logs","product":"sls","label":"로그 서비스","group":"seoul","why":"서버 로그 수집 및 모니터링"}
{"t":"edge","id":"e-gameserver-logs","from":"gameserver","to":"logs","kind":"control","label":"로그 전송"}
